content = open('/home/ubuntu/.hermes/belam-codex/templates/builder-first-pipeline.md').read()
_RE_YAML_BLOCK = re.compile(r'\`\`\`yaml\n(.*?)\n\`\`\`', re.DOTALL)
blocks = list(_RE_YAML_BLOCK.finditer(content))

stage_meta = {}
for yb in blocks:
    yaml_content = yb.group(1)
    lines = yaml_content.split('\n')
    cur_phase = None
    in_stages = False

    for i, yline in enumerate(lines):
        stripped = yline.strip()

        if stripped.startswith('phase') and ':' in stripped:
            phase_key = stripped.split(':')[0].strip()
            if phase_key in ('phase1', 'phase2', 'phase3'):
                cur_phase = phase_key
                in_stages = False

        if stripped.startswith('stages:'):
            in_stages = True
            continue

        if in_stages and stripped.startswith('- role:'):
            role = stripped.split('role:')[1].strip().split()[0]
            stage_lines = [stripped]
            j = i + 1
            while j < len(lines):
                next_stripped = lines[j].strip()
                if next_stripped.startswith('- role:') or (next_stripped and not next_stripped.startswith(' ') and not next_stripped.startswith('-')):
                    break
                if next_stripped:
                    stage_lines.append(next_stripped)
                j += 1

